package com.lamggm.rospocket;
import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.widget.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class PlotUnitPresentationTest {
 PlotController c;PlotView v;String watch="/value",id="/value\ndata";
 void frame(long seq){c.accept(new PlotController.Frame(watch,1,seq,seq*1000,null,Arrays.asList(new PlotController.Field(watch,"data",null,1.25)),new PlotHistory.Source(0,11,12,"rt/value","std_msgs::msg::dds_::Float64_")));}
 @Before public void setup(){c=new PlotController();c.configureProfile(ReadoutPresentationTest.profile().withDashboard(DashboardLayout.defaults().display("watch0",new DashboardLayout.Display("gauge","data",0,2,"m/s"))));frame(1);v=new PlotView(RuntimeEnvironment.getApplication(),c);v.refresh();}
 @Test public void removingAdHocSeriesAlsoRemovesItsUnitAndNativeFilterSelection()throws Exception{c=new PlotController();frame(1);assertTrue(c.select(watch,"data"));v=new PlotView(RuntimeEnvironment.getApplication(),c);v.refresh();v.findViewWithTag("plot-unit:"+id).performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();((EditText)d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit")).setText("V");d.getButton(-1).performClick();assertEquals(1,c.profileSelection().size());v.findViewWithTag("plot-remove:"+id).performClick();assertTrue(c.history.snapshot().isEmpty());assertTrue("Removed ad hoc field must not be saved",c.profileSelection().isEmpty());assertTrue("Removed field must leave native intake",c.numericSelection().fields.isEmpty());}
 @Test public void retiringAdHocSeriesMustNotTurnItsLabelIntoAPersistentNativeSelection()throws Exception{c=new PlotController();frame(1);assertTrue(c.select(watch,"data"));v=new PlotView(RuntimeEnvironment.getApplication(),c);v.refresh();v.findViewWithTag("plot-unit:"+id).performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();((EditText)d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit")).setText("V");d.getButton(-1).performClick();c.retire(watch);assertTrue(c.history.snapshot().isEmpty());assertTrue("Unit metadata must not create intake demand after retirement",c.numericSelection().fields.isEmpty());assertTrue(c.profileSelection().isEmpty());}
 @Test public void retiringAnUnrelatedWatchMustNotCancelHealthySeriesUnitEdit()throws Exception{v.findViewWithTag("plot-unit:"+id).performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();((EditText)d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit")).setText("V");c.retire("Watch 2 · /missing");d.getButton(-1).performClick();assertEquals("V",v.exportSeries().get(0).unit);assertEquals("V",c.profileSelection().get(0).unit);}
 @Test public void returningToPreviewClosesAnyOpenUnitEditor()throws Exception{
  v.findViewWithTag("plot-unit:"+id).performClick();android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing());
  v.previewMode(true,240);assertFalse("Unit editor must not outlive expanded plot",dialog.isShowing());
 }
 @Test public void unitEditorRemainsTouchableInSmallFixedCardWithoutOpeningClippedFieldList()throws Exception{v.tileHeight(300);v.measure(android.view.View.MeasureSpec.makeMeasureSpec(400,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(300,android.view.View.MeasureSpec.EXACTLY));v.layout(0,0,400,300);android.view.View access=v.findViewWithTag("plot-units");assertNotNull("Unit editor must not live behind the clipped field list",access);android.graphics.Rect hit=new android.graphics.Rect();access.getDrawingRect(hit);v.offsetDescendantRectToMyCoords(access,hit);assertTrue(hit.toString(),hit.top>=0&&hit.bottom<=300&&hit.width()>=48&&hit.height()>=48);assertTrue(access.performClick());android.app.AlertDialog picker=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals(1,picker.getListView().getAdapter().getCount());picker.getListView().performItemClick(picker.getListView().getAdapter().getView(0,null,picker.getListView()),0,0);android.app.AlertDialog form=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText field=form.findViewById(android.R.id.content).findViewWithTag("plot-series-unit");assertNotNull(field);field.setText("V");form.getButton(-1).performClick();assertEquals("V",v.exportSeries().get(0).unit);assertEquals(1.25,c.history.points(id).get(0).value,0);}
 @Test public void inheritsOnlyMatchingInstrumentUnitAndDoesNotConvertOrChangeIntake(){String text=ConnectionActivityTest.textOf(v);assertFalse(text,text.contains("unidade desconhecida"));assertTrue(text,text.contains("m/s"));assertEquals(1.25,c.history.points(id).get(0).value,0);assertNull("Raw history metadata is not rewritten",c.history.snapshot().get(0).unit);}
 @Test public void explicitUnitEditorChangesLabelsAndExportButNotPointsOrNativeSelection()throws Exception{long epoch=c.numericSelection().epoch;android.view.View button=v.findViewWithTag("plot-unit:"+id);assertNotNull("Selected series needs a unit editor",button);button.performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText field=d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit");field.setText("km/h");d.getButton(-1).performClick();assertEquals("km/h",v.exportSeries().get(0).unit);assertEquals("km/h",c.profileSelection().get(0).unit);assertEquals(epoch,c.numericSelection().epoch);assertEquals(1.25,c.history.points(id).get(0).value,0);assertEquals(1,c.history.points(id).size());}
 @Test public void cancelledAndRetiredEditorsCannotRelabelReplacementSeries()throws Exception{android.view.View button=v.findViewWithTag("plot-unit:"+id);assertNotNull(button);button.performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();((EditText)d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit")).setText("wrong");c.configureProfile(ReadoutPresentationTest.profile());frame(2);d.getButton(-1).performClick();assertFalse(ConnectionActivityTest.textOf(v).contains("wrong"));assertEquals("",c.profileSelection().get(0).unit);}
 @Test public void pausedValuesStayFrozenWhileOnlyTheirDeclaredLabelChanges()throws Exception{((Button)v.findViewWithTag("plot-pause")).performClick();frame(2);android.view.View button=v.findViewWithTag("plot-unit:"+id);assertNotNull(button);button.performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();((EditText)d.findViewById(android.R.id.content).findViewWithTag("plot-series-unit")).setText("V");d.getButton(-1).performClick();assertTrue(v.pausedForExport());assertEquals(1,v.displayed().get(0).points.size());assertEquals("V",v.displayed().get(0).unit);assertEquals(2,c.history.points(id).size());}
}
